def solve(nums):
    n = len(nums)
    if n < 7: return False
    sums = [0] * n
    sums[0] = nums[0]
    for i in range(1, n): sums[i] = sums[i-1] + nums[i]
    for j in range(3, n - 3):
        targets = set()
        for i in range(1, j - 1):
            if sums[i-1] == sums[j-1] - sums[i]:
                targets.add(sums[i-1])
        for k in range(j + 2, n - 1):
            if sums[n-1] - sums[k] == sums[k-1] - sums[j] and (sums[n-1] - sums[k]) in targets:
                return True
    return False

